                                "args": outer.get("args", ()),
                                "kwargs": {**outer.get("kwargs", {}), **kwargs},
                            },
                        ),
                        receive,
                        send,
                    )
            except Exception:
                pass

    # General case for middleware with _path_routing
    if "/" in path:
        parts = path.split("/", 1)
        if len(parts) >= 2:
            first_part = parts[0]
            for route in self.routes:
                try:
                    # Try to match just the first part of the path
                    match = route.pattern.match(first_part)
                    if match and getattr(route.callback, "_path_routing", False):
                        # This is a middleware with _path_routing
                        new_path, args, kwargs = match
                        # Add defaults to kwargs from the URL pattern.
                        kwargs.update(route.default_args)
                        # Add args or kwargs into the scope
                        outer = scope.get("url_route", {})
                        application = route.callback

                        # Call the middleware with the rest of the path
                        return await application(
                            dict(
                                scope,
                                path_remaining=path[len(first_part)+1:],
                                url_route={
                                    "args": outer.get("args", ()) + args,
                                    "kwargs": {**outer.get("kwargs", {}), **kwargs},
                                },
                            ),
                            receive,
                            send,
                        )
                except Resolver404:
                    pass
